using System;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Drawing;using System.Collections.Generic;
class Usability{static IEnumerable<Control> All(Control c){foreach(Control v in c.Controls){yield return v;foreach(var k in All(v))yield return k;}}
static void Check(bool v,string s){if(!v)throw new Exception(s);}
[STAThread]static void Main(){using(var f=new Atlas()){f.Show();var controls=All(f).ToArray();var main=controls.OfType<TabControl>().First(v=>v.TabPages.Contains(v.TabPages.Cast<TabPage>().FirstOrDefault(p=>p.Text=="Verlauf")));var page=main.TabPages.Cast<TabPage>().Single(v=>v.Text=="Verlauf");main.SelectedTab=page;var tabs=All(page).OfType<TabControl>().Single();var list=All(page).OfType<ListBox>().Single();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var plot=(HistoryPlot)typeof(Atlas).GetField("plot",flags).GetValue(f);plot.Frames.Clear();plot.Frames.Add(new Frame{Kind="mark",Marker="demo",Time=DateTime.UtcNow.Ticks,Message="Probe"});typeof(Atlas).GetMethod("RenderEvents",flags).Invoke(f,null);
foreach(var size in new[]{new Size(1280,830),new Size(920,675)}){f.Size=size;foreach(TabPage selected in tabs.TabPages){tabs.SelectedTab=selected;Application.DoEvents();foreach(var v in All(selected).Where(v=>v.Visible&&(v is Button||v is ComboBox||v is CheckBox))){var pt=v.Parent.PointToScreen(v.Location);var rect=selected.RectangleToScreen(selected.ClientRectangle);Check(pt.X>=rect.Left-1&&pt.X+v.Width<=rect.Right+1,"Überbreite: "+v.Text+" "+size);}if(selected.Text=="WLAN-Signal")Check(plot.ClientSize.Height>=120,"Diagrammhöhe "+plot.ClientSize.Height+" "+size);if(selected.Text=="Ereignisse"){list.SelectedIndex=0;Check(All(selected).OfType<Button>().First(v=>v.Text.StartsWith("Störungsbericht")).Enabled,"Bericht");}if(selected.Text=="Ping"){var combos=All(selected).OfType<ComboBox>().ToArray();combos[1].SelectedIndex=2;Check(combos[0].SelectedIndex==0,"Archivwahl ändert Messziel");}}}Console.WriteLine("OK");}}}